#!/usr/bin/env bash
# CampusLab - sync the DSA problem sheet into a running database.
#
# Applies database/04_sheet_* (generated by tools/problemkit/build.py) in order: a setup
# file, one gzip file per section (one transaction each) and a finish file. Every
# problem is an add-or-update; it NEVER deletes
# problems, so users' submissions, solves, duels and POTD history stay intact.
# Safe to run any number of times.
#
# Usage (on the server, from the repo root):
#   ./scripts/sync_production_problems.sh
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT_DIR"

POSTGRES_CONTAINER="${POSTGRES_CONTAINER:-campuslab-postgres}"
POSTGRES_USER="${POSTGRES_USER:-myuser}"
POSTGRES_DB="${POSTGRES_DB:-campus_lab}"

DOCKER_CMD="docker"
if ! docker info >/dev/null 2>&1 && sudo docker info >/dev/null 2>&1; then
    DOCKER_CMD="sudo docker"
fi

shopt -s nullglob
SHEET_FILES=(database/04_sheet_*)
if [ ${#SHEET_FILES[@]} -eq 0 ]; then
    echo "[-] database/04_sheet_* not found. Generate it with: python3 tools/problemkit/build.py"
    exit 1
fi

psql() {
    $DOCKER_CMD exec -i "$POSTGRES_CONTAINER" psql -U "$POSTGRES_USER" -d "$POSTGRES_DB" -v ON_ERROR_STOP=1 "$@"
}

echo "=========================================================="
echo "   CampusLab - Problem Sheet Sync (add/update, never delete)"
echo "=========================================================="
echo "==> Target: $POSTGRES_CONTAINER / $POSTGRES_DB"

before=$(psql -At -c 'SELECT count(*) FROM "Problem"')
echo "==> Problems before: $before"

for f in "${SHEET_FILES[@]}"; do
    echo "==> Applying $f"
    case "$f" in
        *.gz) gunzip -c "$f" | psql -q ;;
        *) psql -q < "$f" ;;
    esac
done

psql -c 'SELECT count(*) AS total_problems,
                count(number) AS in_sheet,
                count(DISTINCT section) AS sections,
                MIN(jsonb_array_length(testcases)) AS min_tests,
                MAX(jsonb_array_length(testcases)) AS max_tests
         FROM "Problem"'

echo "==> Done. Problems before: $before, after: $(psql -At -c 'SELECT count(*) FROM "Problem"')"
